  test('TFFU-073: link health: linked routes draw a page, not the app\'s "not found" view', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
        const routes = [{"url":"https://with-bugs.practicesoftwaretesting.com/#/contact","route":"/#/contact"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/category/hand-tools","route":"/#/category/hand-tools"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/category/power-tools","route":"/#/category/power-tools"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/category/undefined","route":"/#/category/undefined"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/chainsaws","route":"/#/chainsaws"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/rentals","route":"/#/rentals"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/auth/login","route":"/#/auth/login"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/1","route":"/#/product/1"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/2","route":"/#/product/2"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/3","route":"/#/product/3"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/4","route":"/#/product/4"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/5","route":"/#/product/5"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/6","route":"/#/product/6"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/7","route":"/#/product/7"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/8","route":"/#/product/8"},{"url":"https://with-bugs.practicesoftwaretesting.com/#/product/9","route":"/#/product/9"}];
        // TFP-165: what the app draws for a route - a fresh document, settled (bounded), as text.
        const tfRouteView = async (route: string): Promise<string> => {
          const view = await page.context().newPage();
          try {
            await view.goto(route, { waitUntil: 'domcontentloaded', timeout: 8000 });
            await view.waitForLoadState('networkidle', { timeout: 4000 }).catch(() => {});
            return (await view.locator('body').innerText()).replace(/\s+/g, ' ').trim();
          } finally {
            await view.close();
          }
        };
        // Once per run (per worker): a route that can't exist, and what the app draws for it.
        const tfMissingRoute = (route: string): Promise<{ route: string; view: string }> => {
          const url = new URL(route);
          const prefix = url.origin + url.pathname + (url.hash.startsWith('#!') ? '#!/' : '#/');
          const cache = globalThis as unknown as { __tfMissingRoutes?: Map<string, Promise<{ route: string; view: string }>> };
          cache.__tfMissingRoutes ??= new Map();
          let probe = cache.__tfMissingRoutes.get(prefix);
          if (!probe) {
            const missing = prefix + 'testforge-missing-' + Math.random().toString(36).slice(2, 10);
            probe = tfRouteView(missing).then((view) => ({ route: new URL(missing).pathname + new URL(missing).hash, view }));
            cache.__tfMissingRoutes.set(prefix, probe);
          }
          return probe;
        };
        const deadline = Date.now() + 14000;
        const notFound: string[] = [];
        const notChecked: string[] = [];
        for (const { url, route } of routes) {
            if (Date.now() > deadline) {
                notChecked.push(route);
                continue;
            }
            const probe = await tfMissingRoute(url);
            if ((await tfRouteView(url)) === probe.view) notFound.push(route + ' (draws the same as ' + probe.route + ', a route that cannot exist)');
        }
        if (notChecked.length > 0) {
            test.info().annotations.push({ type: 'finding', description: notChecked.length + ' linked routes not checked: the check stops after 14 s (' + notChecked.slice(0, 5).join(', ') + (notChecked.length > 5 ? ', ...' : '') + ')' });
        }
        expect(notFound, 'linked routes that show the app\'s "not found" view: ' + notFound.join('; ')).toEqual([]);
    });

