  test('TFFU-092: keyboard navigation: links can receive focus and activate with Enter', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page, context }) => {
        const links = [{"text":"","url":"https://with-bugs.practicesoftwaretesting.com/","rawHref":"/","category":"navigation","linkType":"internal","containerLabel":"","expectedStatus":null,"isVisible":true,"target":"","targetBehavior":"same-window","titleAttribute":"Practice Software Testing - Toolshop","downloadName":"","requiresAuth":false,"isSecure":true},{"text":"Home","url":"https://with-bugs.practicesoftwaretesting.com/#/contact","rawHref":"#/contact","category":"navigation","linkType":"internal","containerLabel":"","expectedStatus":null,"isVisible":true,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true},{"text":"Hand Tools","url":"https://with-bugs.practicesoftwaretesting.com/#/category/hand-tools","rawHref":"#/category/hand-tools","category":"navigation","linkType":"internal","containerLabel":"","expectedStatus":null,"isVisible":false,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true}];
        const revisitLinksPage = async () => {
            await page.goto('/#/category/hand-tools');
            await page.waitForLoadState('domcontentloaded');
        };

        // TFP-159: reveal what a closed menu or a collapsed navbar hides. The control is an element with
        // aria-expanded whose aria-controls (or data-bs-target, data-target, href="#id") names a hidden ancestor of the
        // target; failing that, one just before it - nearest ancestor first. A hidden control is revealed first, up to 3 levels.
        const tfReveal = async (target: ReturnType<typeof page.locator>, how: 'keyboard' | 'click'): Promise<{ visible: boolean; reason: string }> => {
          if (await target.isVisible()) return { visible: true, reason: '' };
          const start = await target.elementHandle({ timeout: 2000 }).catch(() => null);
          if (!start) return { visible: false, reason: 'it is not on the page' };
          const chain: Array<NonNullable<Awaited<ReturnType<typeof start.asElement>>>> = [];
          let current = start;
          for (let level = 0; level < 3; level += 1) {
            const toggle = (await current.evaluateHandle((node) => {
              const element = node as Element;
              const shown = (e: Element) => { const s = getComputedStyle(e); const r = e.getBoundingClientRect(); return s.display !== 'none' && s.visibility !== 'hidden' && r.width > 0 && r.height > 0; };
              const toggles = Array.from(document.querySelectorAll('[aria-expanded]'));
              // Nearest hidden ancestor first; at each, a control naming it, then one just before it.
              for (let up = element.parentElement; up && up !== document.body; up = up.parentElement) {
                if (shown(up)) continue;
                const id = up.id;
                const named = id ? toggles.find((t) => t !== element && ((t.getAttribute('aria-controls') ?? '').split(/\s+/).includes(id) || [t.getAttribute('data-bs-target'), t.getAttribute('data-target'), t.getAttribute('href')].includes('#' + id))) : undefined;
                if (named) return named;
                const before = up.previousElementSibling;
                if (before && before.hasAttribute('aria-expanded')) return before;
              }
              return null;
            })).asElement();
            if (!toggle) break;
            chain.unshift(toggle);
            if (await toggle.isVisible()) break;
            current = toggle;
          }
          if (chain.length === 0) return { visible: false, reason: 'no control was found that reveals it' };
          for (const toggle of chain) {
            if (how === 'keyboard') {
              await toggle.focus({ timeout: 2000 }).catch(() => {});
              await page.keyboard.press('Enter');
            } else {
              await toggle.click({ timeout: 2000 }).catch(() => {});
            }
          }
          await target.waitFor({ state: 'visible', timeout: 2000 }).catch(() => {});
          if (await target.isVisible()) return { visible: true, reason: '' };
          const nearest = chain[chain.length - 1];
          const menu = await nearest.evaluate((e) => (e.getAttribute('aria-label') || e.textContent || '').trim().replace(/\s+/g, ' ')) || 'unnamed';
          const opened = (await nearest.getAttribute('aria-expanded')) === 'true';
          return { visible: false, reason: opened ? "the '" + menu + "' menu opened, but it stays hidden" : "the '" + menu + "' menu didn't open" };
        };
        await revisitLinksPage();
        for (const link of links) {
            const locator = !link.isVisible
                ? link.text
                        ? page.getByRole('link', { name: link.text, exact: true, includeHidden: true }).first()
                        : page.locator('a[href="' + (link.rawHref || link.url).replace(/"/g, '\"') + '"]').first()
                : link.text
                ? page.getByRole('link', { name: link.text, exact: true }).first()
                : link.rawHref
                    ? page.locator('a[href="' + link.rawHref.replace(/"/g, '\"') + '"]:visible, a[href="' + link.rawHref.replace(/"/g, '\"') + '"]:has(:visible)').first()
                    : page.locator('a[href="' + link.url.replace(/"/g, '\"') + '"]:visible, a[href="' + link.url.replace(/"/g, '\"') + '"]:has(:visible)').first();
            if (!link.isVisible) {
                // TFP-159: hidden at inspection - open its menu by keyboard first; a link users can't reach fails, naming the menu.
                const reach = await tfReveal(locator, 'keyboard');
                expect(reach.visible, (link.text || link.url) + " can't be reached by keyboard: " + reach.reason).toBeTruthy();
            }
            await locator.focus();
            await expect(locator).toBeFocused();
            const urlBeforeInteraction = page.url();

            if (link.targetBehavior === 'new-tab') {
                const popupPromise = context.waitForEvent('page');
                await page.keyboard.press('Enter');
                const popup = await popupPromise;
                await popup.waitForLoadState('domcontentloaded').catch(() => {});
                // Same host and path; a site that upgrades http to https (the-internet's
                // Elemental Selenium link, a 301) has still opened the right page.
                expect(popup.url().replace(/^https?:\/\//, '')).toContain(link.url.replace(/[#?].*$/, '').replace(/^https?:\/\//, ''));
                await popup.close().catch(() => {});
            } else {
                await page.keyboard.press('Enter');
                // Enter only starts the navigation: waiting for the old page's
                // load state returned at once, the URL looked unchanged, and the
                // next link was then looked for on the new site (TFP-123).
                await page.waitForURL((url) => url.href !== urlBeforeInteraction, { timeout: 5000 }).catch(() => {});

                if (page.url() !== urlBeforeInteraction) {
                    // Straight back to the links page: after a cross-site
                    // redirect, goBack() can land on a hop in between.
                    await revisitLinksPage();
                }
            }
        }
    });

