  test('TFFU-098: navigation link health: Home', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
        await page.goto('/#/product/1');
        await page.waitForLoadState('domcontentloaded');

        const locator = page.getByRole('link', { name: 'Home', exact: true }).first();
        await expect(locator, 'Home is not on the page').toBeAttached();
        await expect(locator).toHaveAttribute('href', '#/contact');

        // TFP-165: what the app draws for a route - a fresh document, settled (bounded), as text.
        const tfRouteView = async (route: string): Promise<string> => {
          const view = await page.context().newPage();
          try {
            await view.goto(route, { waitUntil: 'domcontentloaded', timeout: 8000 });
            await view.waitForLoadState('networkidle', { timeout: 4000 }).catch(() => {});
            return (await view.locator('body').innerText()).replace(/\s+/g, ' ').trim();
          } finally {
            await view.close();
          }
        };
        // Once per run (per worker): a route that can't exist, and what the app draws for it.
        const tfMissingRoute = (route: string): Promise<{ route: string; view: string }> => {
          const url = new URL(route);
          const prefix = url.origin + url.pathname + (url.hash.startsWith('#!') ? '#!/' : '#/');
          const cache = globalThis as unknown as { __tfMissingRoutes?: Map<string, Promise<{ route: string; view: string }>> };
          cache.__tfMissingRoutes ??= new Map();
          let probe = cache.__tfMissingRoutes.get(prefix);
          if (!probe) {
            const missing = prefix + 'testforge-missing-' + Math.random().toString(36).slice(2, 10);
            probe = tfRouteView(missing).then((view) => ({ route: new URL(missing).pathname + new URL(missing).hash, view }));
            cache.__tfMissingRoutes.set(prefix, probe);
          }
          return probe;
        };
        const probe = await tfMissingRoute('https://with-bugs.practicesoftwaretesting.com/#/contact');
        const view = await tfRouteView('https://with-bugs.practicesoftwaretesting.com/#/contact');
        expect(view, '/#/contact draws the same as ' + probe.route + ', a route that cannot exist: the app shows its "not found" view').not.toBe(probe.view);
    });

  test('TFFU-099: navigation link health: Hand Tools', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
        await page.goto('/#/product/1');
        await page.waitForLoadState('domcontentloaded');

        const locator = page.getByRole('link', { name: 'Hand Tools', exact: true, includeHidden: true }).first();
        await expect(locator, 'Hand Tools is not on the page').toBeAttached();
        await expect(locator).toHaveAttribute('href', '#/category/hand-tools');

        // TFP-165: what the app draws for a route - a fresh document, settled (bounded), as text.
        const tfRouteView = async (route: string): Promise<string> => {
          const view = await page.context().newPage();
          try {
            await view.goto(route, { waitUntil: 'domcontentloaded', timeout: 8000 });
            await view.waitForLoadState('networkidle', { timeout: 4000 }).catch(() => {});
            return (await view.locator('body').innerText()).replace(/\s+/g, ' ').trim();
          } finally {
            await view.close();
          }
        };
        // Once per run (per worker): a route that can't exist, and what the app draws for it.
        const tfMissingRoute = (route: string): Promise<{ route: string; view: string }> => {
          const url = new URL(route);
          const prefix = url.origin + url.pathname + (url.hash.startsWith('#!') ? '#!/' : '#/');
          const cache = globalThis as unknown as { __tfMissingRoutes?: Map<string, Promise<{ route: string; view: string }>> };
          cache.__tfMissingRoutes ??= new Map();
          let probe = cache.__tfMissingRoutes.get(prefix);
          if (!probe) {
            const missing = prefix + 'testforge-missing-' + Math.random().toString(36).slice(2, 10);
            probe = tfRouteView(missing).then((view) => ({ route: new URL(missing).pathname + new URL(missing).hash, view }));
            cache.__tfMissingRoutes.set(prefix, probe);
          }
          return probe;
        };
        const probe = await tfMissingRoute('https://with-bugs.practicesoftwaretesting.com/#/category/hand-tools');
        const view = await tfRouteView('https://with-bugs.practicesoftwaretesting.com/#/category/hand-tools');
        expect(view, '/#/category/hand-tools draws the same as ' + probe.route + ', a route that cannot exist: the app shows its "not found" view').not.toBe(probe.view);

        // TFP-159: reveal what a closed menu or a collapsed navbar hides. The control is an element with
        // aria-expanded whose aria-controls (or data-bs-target, data-target, href="#id") names a hidden ancestor of the
        // target; failing that, one just before it - nearest ancestor first. A hidden control is revealed first, up to 3 levels.
        const tfReveal = async (target: ReturnType<typeof page.locator>, how: 'keyboard' | 'click'): Promise<{ visible: boolean; reason: string }> => {
          if (await target.isVisible()) return { visible: true, reason: '' };
          const start = await target.elementHandle({ timeout: 2000 }).catch(() => null);
          if (!start) return { visible: false, reason: 'it is not on the page' };
          const chain: Array<NonNullable<Awaited<ReturnType<typeof start.asElement>>>> = [];
          let current = start;
          for (let level = 0; level < 3; level += 1) {
            const toggle = (await current.evaluateHandle((node) => {
              const element = node as Element;
              const shown = (e: Element) => { const s = getComputedStyle(e); const r = e.getBoundingClientRect(); return s.display !== 'none' && s.visibility !== 'hidden' && r.width > 0 && r.height > 0; };
              const toggles = Array.from(document.querySelectorAll('[aria-expanded]'));
              // Nearest hidden ancestor first; at each, a control naming it, then one just before it.
              for (let up = element.parentElement; up && up !== document.body; up = up.parentElement) {
                if (shown(up)) continue;
                const id = up.id;
                const named = id ? toggles.find((t) => t !== element && ((t.getAttribute('aria-controls') ?? '').split(/\s+/).includes(id) || [t.getAttribute('data-bs-target'), t.getAttribute('data-target'), t.getAttribute('href')].includes('#' + id))) : undefined;
                if (named) return named;
                const before = up.previousElementSibling;
                if (before && before.hasAttribute('aria-expanded')) return before;
              }
              return null;
            })).asElement();
            if (!toggle) break;
            chain.unshift(toggle);
            if (await toggle.isVisible()) break;
            current = toggle;
          }
          if (chain.length === 0) return { visible: false, reason: 'no control was found that reveals it' };
          for (const toggle of chain) {
            if (how === 'keyboard') {
              await toggle.focus({ timeout: 2000 }).catch(() => {});
              await page.keyboard.press('Enter');
            } else {
              await toggle.click({ timeout: 2000 }).catch(() => {});
            }
          }
          await target.waitFor({ state: 'visible', timeout: 2000 }).catch(() => {});
          if (await target.isVisible()) return { visible: true, reason: '' };
          const nearest = chain[chain.length - 1];
          const menu = await nearest.evaluate((e) => (e.getAttribute('aria-label') || e.textContent || '').trim().replace(/\s+/g, ' ')) || 'unnamed';
          const opened = (await nearest.getAttribute('aria-expanded')) === 'true';
          return { visible: false, reason: opened ? "the '" + menu + "' menu opened, but it stays hidden" : "the '" + menu + "' menu didn't open" };
        };
        const reach = await tfReveal(locator, 'click');
        if (!reach.visible) {
            test.info().annotations.push({ type: 'finding', description: 'Hand Tools is healthy by its address, but users can\'t reach it: ' + reach.reason });
        }
    });

