        const canonical = page.locator('link[rel="canonical"]').first();
        await expect(canonical, 'no canonical link on /#/').toHaveAttribute('href', /.+/);

        const href = await canonical.getAttribute('href');
        expect(href).not.toBeNull();

        const canonicalUrl = new URL(href ?? '', page.url());
        const currentUrl = new URL(page.url());
        const canonicalPath = canonicalUrl.pathname.replace(/\/$/, '') || '/';
        const currentPath = currentUrl.pathname.replace(/\/$/, '') || '/';

        expect(canonicalPath, 'the canonical link on /#/ points to a different page').toBe(currentPath);
